static string lower(string s){for(char &c:s) if(c>='A'&&c<='Z') c+=32;return s;}
static string trim(const string&s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'))b--;return s.substr(a,b-a);}
