static bool tokenchar(unsigned char c){return isalnum(c)||strchr("!#$%&'*+-.^_`|~",c);}
static bool token(const string&s){if(s.empty())return false;for(unsigned char c:s)if(c>=128||!tokenchar(c))return false;return true;}
