 if(!num("max_connections",c.maxconn)||!num("header_bytes",c.header)||!num("header_timeout_ms",c.header_to)||!num("idle_timeout_ms",c.idle)||!num("write_timeout_ms",c.write_to)||!num("max_requests",c.maxreq)||!num("pipeline_depth",c.depth)||!num("upstream_timeout_ms",c.up_to)||!num("body_bytes",c.body)||!num("cache_ttl_ms",c.ttl)||!num("cache_bytes",c.cache)||!num("rate_per_second",c.rate,true)||!num("rate_burst",c.burst)||!num("drain_timeout_ms",c.drain))return false;
