struct Header{string name,value;};
struct Req{string method,target,version,path,query,host,body;vector<Header> h;bool close=false,head=false,proxy=false,chunked=false,auth=false;uint64_t length=0;};
static string geth(const vector<Header>&h,const string&n){string r;for(auto&x:h)if(x.name==n){if(!r.empty())r+=", ";r+=x.value;}return r;}
static set<string> tokens(const string&s){set<string>r;for(auto&x:split(s,',')){string v=lower(trim(x));if(!v.empty())r.insert(v);}return r;}
static bool hostparse(const string&s,string&host){string v=trim(s);if(v.empty())return false;size_t p=v.find(':');host=lower(v.substr(0,p));if(host.empty())return false;for(unsigned char c:host)if(!(isalnum(c)||c=='-'||c=='.'))return false;if(p!=string::npos){uint64_t n;if(!number(v.substr(p+1),n)||n>65535)return false;}return true;}
static bool validvalue(const string&s){for(unsigned char c:s)if(c==0||c=='\r'||c=='\n'||(c<32&&c!='\t')||c==127)return false;return true;}
