static int chunks(const string&s,size_t start,uint64_t limit,size_t trailerlim,string&out,size_t&used){size_t p=start;out.clear();while(true){size_t e=s.find("\r\n",p);if(e==string::npos){if(s.size()-p>trailerlim)return -400;return 0;}string line=s.substr(p,e-p);size_t semi=line.find(';');string num=line.substr(0,semi);if(num.empty())return -400;uint64_t n=0;for(char c:num){int x=hexval(c);if(x<0||n>(UINT64_MAX-x)/16)return -400;n=n*16+x;}if(semi!=string::npos&&!validvalue(line.substr(semi+1)))return -400;p=e+2;if(n==0){size_t begin=p;while(true){size_t z=s.find("\r\n",p);if(z==string::npos){if(s.size()-begin>trailerlim)return -400;return 0;}if(z-begin>trailerlim)return -400;if(z==p){used=z+2;return 1;}string t=s.substr(p,z-p);size_t col=t.find(':');if(col==string::npos||!token(t.substr(0,col))||!validvalue(t.substr(col+1)))return -400;p=z+2;}}if(n>limit||out.size()>limit-n)return -413;if(n>SIZE_MAX-p-2)return -400;if(s.size()<p+(size_t)n+2)return 0;if(s.compare(p+n,2,"\r\n")!=0)return -400;out.append(s,p,(size_t)n);p+=(size_t)n+2;}}
