static void startup(Client*c){c->upidx=(int)((rr++)%cfg.ups.size());int fd=-1;while(!pool[c->upidx].empty()){fd=pool[c->upidx].back();pool[c->upidx].pop_back();char x;int z=recv(fd,&x,1,MSG_PEEK|MSG_DONTWAIT);if(z==0||(z<0&&errno!=EAGAIN&&errno!=EWOULDBLOCK)){close(fd);fd=-1;continue;}if(z>0){close(fd);fd=-1;continue;}break;}bool fresh=fd<0;if(fresh){fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){upfail(c,false);return;}int z=connect(fd,(sockaddr*)&cfg.upaddr[c->upidx],sizeof(sockaddr_in));if(z<0&&errno!=EINPROGRESS){close(fd);upfail(c,false);return;}c->upconnecting=z<0;}else c->upconnecting=false;c->up=fd;upstream[fd]=c;c->up_start=nowms();c->upin.clear();c->upsent=0;c->upsending=true;string rest=c->req.path.substr(cfg.proxy.size());string target="/"+rest+c->req.query;c->upout=c->req.method+" "+target+" HTTP/1.1\r\nHost: "+cfg.ups[c->upidx]+"\r\n";auto hop=hopset(c->req.h);hop.insert("host");for(auto&h:c->req.h)if(!hop.count(h.name))c->upout+=h.name+": "+h.value+"\r\n";c->upout+="Content-Length: "+to_string(c->req.body.size())+"\r\nConnection: keep-alive\r\n\r\n"+c->req.body;add(fd,EPOLLOUT|EPOLLRDHUP);mod(c->fd,EPOLLRDHUP);}
static bool responseparse(Client*c){string&s=c->upin;size_t e=s.find("\r\n\r\n");if(e==string::npos){if(s.size()>cfg.header){upfail(c,false);return true;}return false;}if(e+4>cfg.header){upfail(c,false);return true;}size_t p=s.find("\r\n");string line=s.substr(0,p);if(p==string::npos||line.size()<12||(line.compare(0,9,"HTTP/1.1 ")&&line.compare(0,9,"HTTP/1.0 "))||!isdigit(line[9])||!isdigit(line[10])||!isdigit(line[11])||(line.size()>12&&line[12]!=' ')){upfail(c,false);return true;}int status=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';if(status<200||status>599){upfail(c,false);return true;}vector<Header> h;int cl=0,te=0;uint64_t n=0;string tv;size_t i=p+2;while(i<e){size_t j=s.find("\r\n",i);if(j==string::npos||j>e){upfail(c,false);return true;}string l=s.substr(i,j-i);size_t k=l.find(':');if(k==string::npos||!token(l.substr(0,k))||!validvalue(l.substr(k+1))){upfail(c,false);return true;}string name=lower(l.substr(0,k)),v=trim(l.substr(k+1));h.push_back({name,v});if(name=="content-length"){cl++;if(!number(v,n)){upfail(c,false);return true;}}if(name=="transfer-encoding"){te++;tv=lower(v);}i=j+2;}if(cl>1||te>1||(cl&&te)||(te&&tv!="chunked")){upfail(c,false);return true;}bool nobody=c->req.head||status==204||status==304;string body;size_t used=e+4;if(!nobody){if(te){int z=chunks(s,e+4,cfg.body,cfg.header,body,used);if(z<0){upfail(c,false);return true;}if(!z)return false;}else if(cl){if(n>cfg.body){upfail(c,false);return true;}if(s.size()-e-4<n)return false;body=s.substr(e+4,n);used=e+4+n;}else{upfail(c,false);return true;}}else if(!cl&&!te)n=0;
 if(used!=s.size()){upfail(c,false);return true;}auto hop=hopset(h);string extra;for(auto&x:h)if(!hop.count(x.name))extra+=x.name+": "+x.value+"\r\n";bool reusable=line.compare(0,8,"HTTP/1.1")==0&&!tokens(geth(h,"connection")).count("close");delup(c,reusable);uint64_t repr=c->req.head&&cl?n:body.size();
 if(c->req.method=="GET"&&status==200&&!c->req.auth&&geth(h,"set-cookie").empty()){string cc=lower(geth(h,"cache-control"));bool pub=false,ban=false,agefound=false;uint64_t age=0;for(auto part:split(cc,',')){part=trim(part);if(part=="public")pub=true;if(part=="private"||part=="no-store"||part.rfind("private=",0)==0)ban=true;if(part.rfind("max-age=",0)==0)agefound=number(trim(part.substr(8)),age);}string vary=lower(trim(geth(h,"vary")));bool v=vary=="accept-encoding";if(pub&&!ban&&agefound&&age>0&&(vary.empty()||v)){uint64_t duration=age>UINT64_MAX/1000?cfg.ttl:min<uint64_t>(cfg.ttl,age*1000);if(duration)cacheput(cachekey(c->req,v),{status,extra,body,nowms()+(long long)duration});}}
 respond(c,status,extra,body,repr);return true;}
static void process(Client*c){if(c->writing||c->up>=0)return;while(true){if(!c->havehead){if(c->input.empty()){c->first=0;c->idle=nowms();mod(c->fd,EPOLLIN|EPOLLRDHUP);return;}if(!c->first)c->first=nowms();size_t e=c->input.find("\r\n\r\n");size_t scan=e==string::npos?c->input.size():e+4;for(size_t i=0;i<scan;i++){if(c->input[i]=='\0'||(c->input[i]=='\n'&&(i==0||c->input[i-1]!='\r'))||(c->input[i]=='\r'&&i+1<scan&&c->input[i+1]!='\n')){c->req=Req{};fail(c,400);return;}}if(e==string::npos){if(c->input.size()>cfg.header){c->req=Req{};fail(c,431);return;}mod(c->fd,EPOLLIN|EPOLLRDHUP);return;}if(e+4>cfg.header){c->req=Req{};fail(c,431);return;}c->req=Req{};int er=parsehead(c->input.substr(0,e+4),cfg,c->req);if(er){fail(c,er,"",true);return;}c->headend=e+4;c->havehead=true;}
 size_t used=c->headend;if(c->req.chunked){string body;int z=chunks(c->input,c->headend,cfg.body,cfg.header,body,used);if(z<0){fail(c,-z);return;}if(!z){mod(c->fd,EPOLLIN|EPOLLRDHUP);return;}c->req.body=move(body);}else{if(c->input.size()-c->headend<c->req.length){mod(c->fd,EPOLLIN|EPOLLRDHUP);return;}c->req.body=c->input.substr(c->headend,c->req.length);used+=c->req.length;}
 c->input.erase(0,used);c->havehead=false;c->first=0;if(cfg.rate){long long now=nowms();bucket=min<double>(cfg.burst,bucket+(now-bucktime)*cfg.rate/1000.0);bucktime=now;if(bucket<1){respond(c,429,"Retry-After: 1\r\n");return;}bucket-=1;}
 if(c->req.proxy){if(cacheget(c))return;c->attempt=0;startup(c);return;}local(c);return;}}
static void readclient(Client*c){char buf[16384];while(true){size_t cap=(size_t)min<uint64_t>(cfg.body+cfg.header*2+65536,32*1024*1024);if(c->input.size()>=cap){fail(c,413);return;}ssize_t n=recv(c->fd,buf,min(sizeof(buf),cap-c->input.size()),0);if(n>0){if(c->input.empty()&&!c->first)c->first=nowms();c->input.append(buf,n);c->idle=nowms();process(c);if(c->writing||c->up>=0)return;}else if(n==0){destroy(c);return;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)return;else{destroy(c);return;}}}
static void writeclient(Client*c){while(c->sent<c->output.size()){ssize_t n=send(c->fd,c->output.data()+c->sent,c->output.size()-c->sent,MSG_NOSIGNAL);if(n>0){c->sent+=n;c->write_start=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;else{destroy(c);return;}}while(c->remain){ssize_t n=sendfile(c->fd,c->file,&c->offset,min<uint64_t>(c->remain,1<<20));if(n>0){c->remain-=n;c->write_start=nowms();}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;else{destroy(c);return;}}if(c->file>=0){close(c->file);c->file=-1;}c->output.clear();c->writing=false;if(c->closing){destroy(c);return;}c->idle=nowms();process(c);}
static void upstream_event(Client*c,uint32_t ev){if(c->up<0)return;if(c->upconnecting){int err=0;socklen_t l=sizeof err;if(getsockopt(c->up,SOL_SOCKET,SO_ERROR,&err,&l)<0||err){upfail(c,false);return;}c->upconnecting=false;}if(c->upsending&&(ev&EPOLLOUT)){while(c->upsent<c->upout.size()){ssize_t n=send(c->up,c->upout.data()+c->upsent,c->upout.size()-c->upsent,MSG_NOSIGNAL);if(n>0)c->upsent+=n;else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;else{upfail(c,false);return;}}c->upsending=false;mod(c->up,EPOLLIN|EPOLLRDHUP);}
 if(!c->upsending&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP|EPOLLERR))){char b[16384];while(true){ssize_t n=recv(c->up,b,sizeof b,0);if(n>0){c->upin.append(b,n);if(c->upin.size()>cfg.body+cfg.header*2+65536){upfail(c,false);return;}if(responseparse(c))return;}else if(n==0){upfail(c,false);return;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{upfail(c,false);return;}}}else if(ev&(EPOLLHUP|EPOLLERR)){upfail(c,false);}}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;configfile=argv[2];if(!load(configfile,cfg))return 1;signal(SIGPIPE,SIG_IGN);signal(SIGHUP,sigh);signal(SIGTERM,sigh);listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof one);if(bind(listener,(sockaddr*)&cfg.listenaddr,sizeof cfg.listenaddr)||listen(listener,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;add(listener,EPOLLIN);pool.resize(cfg.ups.size());bucket=cfg.burst;bucktime=nowms();epoll_event evs[512];while(true){if(hup){hup=0;Config n;if(load(configfile,n)&&n.listen==cfg.listen){for(auto&v:pool)for(int fd:v)close(fd);pool.clear();pool.resize(n.ups.size());cfg=move(n);cache.clear();cacheorder.clear();cachesize=0;bucket=cfg.burst;bucktime=nowms();}}if(term&&stopat==0){stopat=nowms()+cfg.drain;epoll_ctl(ep,EPOLL_CTL_DEL,listener,nullptr);close(listener);listener=-1;}if(term&&(clients.empty()||nowms()>=stopat))break;int count=epoll_wait(ep,evs,512,50);for(int i=0;i<count;i++){int fd=evs[i].data.fd;uint32_t ev=evs[i].events;if(fd==listener){while(true){int s=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0){if(errno==EINTR)continue;break;}if(clients.size()>=cfg.maxconn){close(s);continue;}Client*c=new Client;c->fd=s;c->idle=nowms();clients[s]=c;add(s,EPOLLIN|EPOLLRDHUP);}continue;}auto u=upstream.find(fd);if(u!=upstream.end()){upstream_event(u->second,ev);continue;}auto it=clients.find(fd);if(it==clients.end())continue;Client*c=it->second;if(ev&(EPOLLERR|EPOLLHUP)){destroy(c);continue;}if(c->writing&&(ev&EPOLLOUT)){writeclient(c);continue;}if(!c->writing&&c->up<0&&(ev&EPOLLIN)){readclient(c);continue;}if(ev&EPOLLRDHUP){destroy(c);}}
 long long now=nowms();vector<int> ids;ids.reserve(clients.size());for(auto&x:clients)ids.push_back(x.first);for(int fd:ids){auto it=clients.find(fd);if(it==clients.end())continue;Client*c=it->second;if(c->up>=0&&now-c->up_start>=(long long)cfg.up_to){upfail(c,true);continue;}if(c->writing&&now-c->write_start>=(long long)cfg.write_to){destroy(c);continue;}if(!c->writing&&c->up<0){if(c->first&&now-c->first>=(long long)cfg.header_to){fail(c,400);continue;}if(!c->first&&now-c->idle>=(long long)cfg.idle){destroy(c);continue;}}}}
 for(auto&v:pool)for(int fd:v)close(fd);return 0;}
